tool.command:

  ln -f -s ${input_ligand_path} ${input_ligand_path}_`echo $$`.${input_ligand_path.ext};

  ln -f -s ${input_receptor_path} ${input_receptor_path}_`echo $$`.${input_receptor_path.ext};

  ln -f -s ${input_box_path} ${input_box_path}_`echo $$`.${input_box_path.ext};

  ln -f -s ${input_autobox_path} ${input_autobox_path}_`echo $$`.${input_autobox_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

gnina_run

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__cpu__dq__:${properties.cpu},__dq__exhaustiveness__dq__:${properties.exhaustiveness},__dq__num_modes__dq__:${properties.num_modes},__dq__min_rmsd_filter__dq__:${properties.min_rmsd_filter},__dq__num_mc_saved__dq__:${properties.num_mc_saved},__dq__seed__dq__:${properties.seed},__dq__scoring__dq__:__dq__${properties.scoring}__dq__,__dq__cnn_scoring__dq__:__dq__${properties.cnn_scoring}__dq__,__dq__cnn__dq__:__dq__${properties.cnn}__dq__,__dq__pose_sort_order__dq__:__dq__${properties.pose_sort_order}__dq__,__dq__autobox_add__dq__:${properties.autobox_add},__dq__autobox_extend__dq__:${properties.autobox_extend},__dq__minimize__dq__:${properties.minimize},__dq__score_only__dq__:${properties.score_only},__dq__local_only__dq__:${properties.local_only},__dq__no_gpu__dq__:${properties.no_gpu},__dq__device__dq__:${properties.device},__dq__quiet__dq__:${properties.quiet},__dq__binary_path__dq__:__dq__${properties.binary_path}__dq____cc____cc__'
  #end if

  #if str($input_ligand_path) != 'None':
    --input_ligand_path ${input_ligand_path}_`echo $$`.${input_ligand_path.ext}
  #end if

  #if str($input_receptor_path) != 'None':
    --input_receptor_path ${input_receptor_path}_`echo $$`.${input_receptor_path.ext}
  #end if

  #if str($input_box_path) != 'None':
    --input_box_path ${input_box_path}_`echo $$`.${input_box_path.ext}
  #end if

  #if str($input_autobox_path) != 'None':
    --input_autobox_path ${input_autobox_path}_`echo $$`.${input_autobox_path.ext}
  #end if


  --output_sdf_path $outname_output_sdf_path

  --output_summary_path $outname_output_summary_path

  --output_log_path $outname_output_log_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_ligand_path}_`echo $$`.${input_ligand_path.ext};

  rm -f ${input_receptor_path}_`echo $$`.${input_receptor_path.ext};

  rm -f ${input_box_path}_`echo $$`.${input_box_path.ext};

  rm -f ${input_autobox_path}_`echo $$`.${input_autobox_path.ext};


  if test -f $outname_output_sdf_path; then mv $outname_output_sdf_path $output_sdf_path; fi;

  if test -f $outname_output_summary_path; then mv $outname_output_summary_path $output_summary_path; fi;

  if test -f $outname_output_log_path; then mv $outname_output_log_path $output_log_path; fi;
